def init_streams(
    config: Config,
    environment: Any,
    functions: ServiceFunctions,
) -> ServiceStreams:
    named = config.named
    streams = ServiceStreams()
    streams.consume_activity_job = transformation.Input[str, str, Exception](named.streams.consume_activity_job, environment)
    streams.activity_pause = transformation.Delay[str](named.streams.activity_pause, streams.consume_activity_job, functions.activity_pause)
    streams.consume_fan_out_workflow_job = transformation.Input[str, object, Exception](named.streams.consume_fan_out_workflow_job, environment)
    streams.call_fan_out_activity_a = transformation.SinkWithResult[str, str, Exception](named.streams.call_fan_out_activity_a, streams.consume_fan_out_workflow_job)
    streams.split_activity_a_result = transformation.Split[str](named.streams.split_activity_a_result, streams.call_fan_out_activity_a)
    streams.call_fan_out_activity_b = transformation.SinkWithResult[str, str, Exception](named.streams.call_fan_out_activity_b, streams.split_activity_a_result.add_stream())
    streams.call_fan_out_activity_c = transformation.SinkWithResult[str, str, Exception](named.streams.call_fan_out_activity_c, streams.split_activity_a_result.add_stream())
    streams.consume_workflow_job = transformation.Input[str, str, Exception](named.streams.consume_workflow_job, environment)
    streams.workflow_pause = transformation.Delay[str](named.streams.workflow_pause, streams.consume_workflow_job, functions.workflow_pause)
    streams.call_sequential_activity_a = transformation.SinkWithResult[str, str, Exception](named.streams.call_sequential_activity_a, streams.workflow_pause)
    streams.call_sequential_activity_b = transformation.SinkWithResult[str, str, Exception](named.streams.call_sequential_activity_b, streams.call_sequential_activity_a)
    streams.consume_fan_out_activity_a = transformation.Input[str, str, Exception](named.streams.consume_fan_out_activity_a, environment)
    streams.consume_fan_out_activity_b = transformation.Input[str, str, Exception](named.streams.consume_fan_out_activity_b, environment)
    streams.consume_fan_out_activity_c = transformation.Input[str, str, Exception](named.streams.consume_fan_out_activity_c, environment)
    streams.consume_sequential_activity_a = transformation.Input[str, str, Exception](named.streams.consume_sequential_activity_a, environment)
    streams.consume_sequential_activity_b = transformation.Input[str, str, Exception](named.streams.consume_sequential_activity_b, environment)
    streams.local_schedule = transformation.Input[str, object, Exception](named.streams.local_schedule, environment)
    streams.split_on_demand_jobs = transformation.Split[str](named.streams.split_on_demand_jobs, streams.local_schedule)
    streams.submit_activity_job = transformation.SinkWithResult[str, str, Exception](named.streams.submit_activity_job, streams.split_on_demand_jobs.add_stream())
    streams.observe_activity_result = transformation.Map[str, str](named.streams.observe_activity_result, streams.submit_activity_job, functions.observe_activity_result)
    streams.observe_fan_out_activity_b = transformation.Map[str, str](named.streams.observe_fan_out_activity_b, streams.call_fan_out_activity_b, functions.observe_fanout_activity_b)
    streams.observe_fan_out_activity_c = transformation.Map[str, str](named.streams.observe_fan_out_activity_c, streams.call_fan_out_activity_c, functions.observe_fanout_activity_c)
    streams.submit_workflow_job = transformation.SinkWithResult[str, str, Exception](named.streams.submit_workflow_job, streams.split_on_demand_jobs.add_stream())
    streams.observe_workflow_result = transformation.Map[str, str](named.streams.observe_workflow_result, streams.submit_workflow_job, functions.observe_workflow_result)
    streams.process_activity_job = transformation.Map[str, str](named.streams.process_activity_job, streams.activity_pause, functions.process_activity_job)
    streams.process_fan_out_activity_a = transformation.Map[str, str](named.streams.process_fan_out_activity_a, streams.consume_fan_out_activity_a, functions.process_fanout_activity_a)
    streams.process_fan_out_activity_b = transformation.Map[str, str](named.streams.process_fan_out_activity_b, streams.consume_fan_out_activity_b, functions.process_fanout_activity_b)
    streams.process_fan_out_activity_c = transformation.Map[str, str](named.streams.process_fan_out_activity_c, streams.consume_fan_out_activity_c, functions.process_fanout_activity_c)
    streams.temporal_activity_schedule = transformation.Input[str, str, Exception](named.streams.temporal_activity_schedule, environment)
    streams.scheduled_activity_pause = transformation.Delay[str](named.streams.scheduled_activity_pause, streams.temporal_activity_schedule, functions.scheduled_activity_pause)
    streams.process_scheduled_activity = transformation.Map[str, str](named.streams.process_scheduled_activity, streams.scheduled_activity_pause, functions.process_scheduled_activity)
    streams.temporal_workflow_schedule = transformation.Input[str, str, Exception](named.streams.temporal_workflow_schedule, environment)
    streams.scheduled_workflow_pause = transformation.Delay[str](named.streams.scheduled_workflow_pause, streams.temporal_workflow_schedule, functions.scheduled_workflow_pause)
    streams.process_scheduled_workflow = transformation.Map[str, str](named.streams.process_scheduled_workflow, streams.scheduled_workflow_pause, functions.process_scheduled_workflow)
    streams.process_sequential_activity_a = transformation.Map[str, str](named.streams.process_sequential_activity_a, streams.consume_sequential_activity_a, functions.process_sequential_activity_a)
    streams.process_sequential_activity_b = transformation.Map[str, str](named.streams.process_sequential_activity_b, streams.consume_sequential_activity_b, functions.process_sequential_activity_b)
    streams.process_workflow_job = transformation.Map[str, str](named.streams.process_workflow_job, streams.call_sequential_activity_b, functions.process_workflow_job)
    streams.submit_fan_out_workflow_job = transformation.Sink[str, Exception](named.streams.submit_fan_out_workflow_job, streams.split_on_demand_jobs.add_stream())
    streams.consume_activity_job.set_source(streams.process_activity_job)
    streams.consume_workflow_job.set_source(streams.process_workflow_job)
    streams.consume_fan_out_activity_a.set_source(streams.process_fan_out_activity_a)
    streams.consume_fan_out_activity_b.set_source(streams.process_fan_out_activity_b)
    streams.consume_fan_out_activity_c.set_source(streams.process_fan_out_activity_c)
    streams.consume_sequential_activity_a.set_source(streams.process_sequential_activity_a)
    streams.consume_sequential_activity_b.set_source(streams.process_sequential_activity_b)
    streams.temporal_activity_schedule.set_source(streams.process_scheduled_activity)
    streams.temporal_workflow_schedule.set_source(streams.process_scheduled_workflow)
    return streams